def parse_duration(text: str) -> float:
    if not text or not text.startswith('P'):
        raise ValueError("Duration must start with 'P'")

    text = text[1:]  # Remove 'P'

    # Split by 'T' to separate date and time parts
    if 'T' in text:
        date_part, time_part = text.split('T')
        if not time_part:
            raise ValueError("'T' must be followed by at least one time component")
    else:
        date_part = text
        time_part = None

    total_seconds = 0.0

    # Parse date part (weeks or days)
    if date_part:
        if date_part.endswith('W'):
            # Weeks only
            if time_part:
                raise ValueError("Weeks cannot be combined with time components")
            week_str = date_part[:-1]
            if not week_str:
                raise ValueError("Invalid duration: missing value for W")
            try:
                weeks = float(week_str.replace(',', '.'))
                total_seconds += weeks * 7 * 86400
            except ValueError:
                raise ValueError(f"Invalid weeks value: {week_str}")
        elif date_part.endswith('D'):
            # Days
            day_str = date_part[:-1]
            if not day_str:
                raise ValueError("Invalid duration: missing value for D")
            try:
                days = float(day_str.replace(',', '.'))
                total_seconds += days * 86400
            except ValueError:
                raise ValueError(f"Invalid days value: {day_str}")
        else:
            raise ValueError("Date part must end with 'W' or 'D'")

    # Parse time part (hours, minutes, seconds)
    if time_part:
        i = 0
        while i < len(time_part):
            # Find the next letter
            j = i
            while j < len(time_part) and time_part[j] not in 'HMS':
                j += 1

            if j == len(time_part):
                raise ValueError("Time part must contain H, M, or S")

            value_str = time_part[i:j]
            unit = time_part[j]

            if not value_str:
                raise ValueError(f"Missing value for {unit}")

            try:
                value = float(value_str.replace(',', '.'))
            except ValueError:
                raise ValueError(f"Invalid {unit} value: {value_str}")

            if unit == 'H':
                total_seconds += value * 3600
            elif unit == 'M':
                total_seconds += value * 60
            elif unit == 'S':
                total_seconds += value

            i = j + 1

        # Check for invalid characters in time part
        if i != len(time_part):
            raise ValueError("Invalid characters in time part")

    # At least one component must be present
    if total_seconds == 0.0 and not date_part and not time_part:
        raise ValueError("At least one duration component must be present")

    return total_seconds
